opts={'A':8,'B':65,'C':42,'D':63}
fits=[k for k,d in opts.items() if all((8**m-1)%d==0 for m in range(2,40,2))]
assert fits==['D']

import sympy as sp
opts={'A':45,'B':30,'C':90,'D':60}
def f(d):
    t=sp.rad(d)
    return sp.simplify(sp.cot(t)**2-2*sp.cos(t)**2)
fits=[k for k,d in opts.items() if 0<d<90 and f(d)==0]
assert fits==['A']
